CREATE TABLE IF NOT EXISTS fleet_node_operation (id UUID NOT NULL DEFAULT gen_random_uuid(), node_id UUID NOT NULL, operation TEXT NOT NULL, phase TEXT NOT NULL, idempotency_key TEXT NOT NULL DEFAULT '', request_fingerprint TEXT NOT NULL DEFAULT '', approved_at TIMESTAMPTZ, retry_count INT NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
